"use client"

import React from "react"
import { cn } from "@/lib/utils"

interface ShinyTextProps {
  text: string
  disabled?: boolean
  speed?: number
  className?: string
}

export const ShinyText: React.FC<ShinyTextProps> = ({
  text,
  disabled = false,
  speed = 5,
  className = "",
}) => {
  return (
    <span
      className={cn(
        "relative inline-block bg-gradient-to-r from-accent-gold via-white to-accent-gold bg-[length:200%_100%] bg-clip-text text-transparent",
        !disabled && "animate-[shiny-text_5s_linear_infinite]",
        disabled && "opacity-50 cursor-not-allowed",
        className
      )}
    >
      {text}
    </span>
  )
}
